std::vector<Point2d> result;
std::size_t n = segments.size();
for (std::size_t i = 0; i < n; ++i) {
    const Segment2d& s1 = segments[i];
    for (std::size_t j = i + 1; j < n; ++j) {
        const Segment2d& s2 = segments[j];
        CK_Segment_2 cgalSeg1(CK_Point_2(s1.p1().x(), s1.p1().y()), CK_Point_2(s1.p2().x(), s1.p2().y()));
        CK_Segment_2 cgalSeg2(CK_Point_2(s2.p1().x(), s2.p1().y()), CK_Point_2(s2.p2().x(), s2.p2().y()));
        auto o = CGAL::intersection(cgalSeg1, cgalSeg2);
        if (const CK_Point_2* ip = CGAL::object_cast<CK_Point_2>(&o)) {
            result.push_back(Point2d(ip->x(), ip->y()));
        }
    }
}
return result;

